    ['指数写法（小写 e）', '1e3'],
    ['指数写法（大写 E）', '1.5E2'],
    ['千位分隔符', '1,000.00'],
    ['超过两位小数', '12.345'],
    ['更多位小数', '12.3456'],
    ['售价作为 JSON 整数数字提交', 12],
    ['售价作为 JSON 小数数字提交', 12.5],
    ['空字符串', ''],
    ['空值 null', null],
  ];

  for (const [label, price] of badPrices) {
