  // 规格 1：颜色/红色（稍后删除）+ 尺码/纯空白值（保留，首次提交因此被拒绝）
  fill(cards[0], [['颜色', '红色'], ['尺码', '   ']], '88.00', '6');
  // 规格 2：稍后整条删除，它的属性、售价、库存都不能被带上
