  fill(cards[2], [['颜色', '绿色'], ['尺码', '均码']], '12.345', '0');
  // 删除整条中间规格，再删除第一条规格中靠前的属性
  cards[1].querySelector('.remove-spec').click();
  cards[0].querySelectorAll('.remove-attr')[0].click();
  return document.querySelectorAll('#specs [data-spec]').length;
